def transform(grid):
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    foreground = next(v for v in range(10) if v != background and any(v in row for row in grid))
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == foreground and row[c] == background and row[c + 1] == foreground:
                out[r][c] = 2
    return out

